  + Status : string
}

class MENSOUser {
  + HomeAddress : string
  + OfficeAddress : string
  + WorkingHours : string
}

class MENSOCard {
  + CardNumber : string
}

class Trip {
  + Time : time
  + Date : date
}

class Invoice {
  + Amount : float
  + Discount : float
}

class TicketMachine {
  + RegisterTrip(trip)
}

BusCompany "1" -- "0..*" Bus
