BusCompany "1" -- "0..*" Line
BusCompany "1" -- "0..*" ApprovalProcess
BusCompany "1" -- "0..*" MENSOUser
BusCompany "1" -- "0..*" Invoice

Line "1" -- "1..*" Trajectory
Line "1" -- "0..*" Trip

Trajectory "0..1" -- "0..*" Bus : assigned to

MENSOUser "1" -- "1" MENSOCard
MENSOUser "1" -- "0..*" Invoice

MENSOCard "1" -- "0..*" Trip
Line "1" -- "0..*" Trip
Trip "0..*" -- "1" TicketMachine

Invoice "1" -- "0..*" Trip : includes

@enduml

